nodes.statement:
The spectrum of $\frac{1}{N_2}\Xi\Xi^T$ is localised in an interval with large probability:

\begin{equation} \mathbb P(\|\frac {1}{N_2}\Xi\Xi^T-\mathbb I\|_{op}\geq t+\sqrt{\lambda_+}-1)\leq 2e^{-\frac {N_1t^2}{2}}\,. 
\end{equation}

\begin{cases}
\sigma_{N,R}(dx)&\mbox{uniform on $S^N(R)$}\,;\\
\gamma_{N,\theta}(dx)&\mbox{centred Gaussian with covariance $\theta \mathbb I$}\,.
\end{cases}

We will prove the following equivalence at the level of free energies, which can be related by a marginalisation (m) or a Legendre transform (LT): 

\

\begin{center}
\begin{tikzcd}
  HM_\sigma \arrow[r,leftrightarrow, "m", blue] \arrow[d,leftrightarrow,"LT", blue]
    & RBM_{\sigma,\gamma} \arrow[d,leftrightarrow,"LT", blue] \arrow[r,leftrightarrow, "LT",red]&RBM_{\sigma\sigma}\arrow[r,leftrightarrow, "LT",red]&RBM_{\rho^2}\\
  HM_{\rho} \arrow[r, leftrightarrow, "m", blue]
&RBM_{\rho\gamma} \arrow[ru,leftrightarrow, "LT",red] \end{tikzcd}
\end{center}

We will not concern here about low-load ($\alpha=0,1$), yet some of the equivalences we state hold also in this regime. More precisely, red arrows indicate equivalences valid only in high load while blue arrow equivalences hold regardless of $\alpha$.

The main idea is very simple; we briefly outline the heuristics for the equivalence $RBM_{\sigma\sigma}\xleftrightarrow{LT} RBM_{\rho^2}$ (the other cases are similar). By the standard disintegration of finite-dimensional Gaussian measures into spheres we have
\begin{eqnarray}
&&\int_{\mathbb{R}^{N_1}\times \mathbb{R}^{N_1} }\mu^2(dxdy)e^{-\beta H(x,y)}\nonumber\\
&=&\int_{0}^{\infty} dR_1\int_{0}^{\infty}dR_2 e^{-\sqrt{N_1N_2}r\left(\frac{R_1}{\sqrt{N_1}},\frac{R_2}{\sqrt{N_2}}\right)-\frac{R_1}{2\theta_1}-\frac{R_2}{2\theta_2}}\nonumber\\
&&\frac{|S_{N_1}(R_1)\times S_{N_2}(R_2)|}{\sqrt{2\pi\theta}^{N_1+N_2}}\int_{S_{N_1}(R_1)\times S_{N_2}(R_2)}\sigma_{N_1,R_1}(dx)\sigma_{N_2,R_2}(dy)e^{-\beta H(x,y)}\,. \end{eqnarray}
We adjusted the normalisation of the inner integral so to get the partition function of $RBM_{\sigma\sigma}$. Thus we continue the chain of identities as
\begin{equation}
\eqref{eq:cont}=\int_{0}^{\infty} dR_1\int_{0}^{\infty}dR_2 e^{-\sqrt{N_1N_2}r\left(\frac{R_1}{\sqrt{N_1}},\frac{R_2}{\sqrt{N_2}}\right)-\frac{R_1}{2\theta_1}-\frac{R_2}{2\theta_2}+\log\left(\frac{|S_{N_1}(R_1)\times S_{N_2}(R_2)|}{\sqrt{2\pi\theta}^{N_1+N_2}}\right)+(N_1+N_2)A_{\sigma\sigma}(R_1,R_2)}\,. 
\end{equation}
Then we can evaluate the integral by the usual Laplace method, since by a simple scaling argument the maximum must be attained at the scale $R_1,R_2\sim\sqrt{N_1+N_2}$.

Assume $\bf P1), P2)$ and let $\rho_N, \rho^2_N$ be defined as in (\ref{eq:Reg-prior1}), (\ref{eq:Reg-prior2}) and discussion around. Then
\begin{itemize}
\item[i)] $HM_{\sigma}\xleftrightarrow{LT} HM_{\rho}$:
\begin{equation} A_\rho(\theta,\alpha,\beta)=\alpha \sup_{R>0}\left( \alpha^{-1}A_{\sigma}(R,\beta) -\frac{R^2}{2\theta}+\log R- r(R) -\frac12(\log\theta-1) \right)\,;
\end{equation}
\begin{equation} A_{\sigma}(R,\beta)=\alpha \inf_{\theta>0}\left(\frac{R^2}{2\theta}+\alpha^{-1}A_\rho(\theta,\alpha,\beta) -\log R+ r(R)+\frac12(\log\theta-1)\right)\,.
\end{equation}
\item[ii)] $RBM_{\sigma\sigma}\xleftrightarrow{LT} RBM_{\sigma,\gamma}$:
\begin{equation} A_{\sigma,\gamma}(\theta,R_2,\alpha,\beta)=\alpha\sup_{R_1>0}\left(\alpha^{-1}A_{\sigma\sigma}(R_1,R_2,\beta)-\frac{R_1^2}{2\theta}+\log R_1 -\frac12(\log\theta-1)\right)\,;
\end{equation}
\begin{equation} A_{\sigma\sigma}(R_1,R_2,\beta)=\alpha\inf_{\theta>0}\left(\frac{R_1^2}{2\theta}+\alpha^{-1}A_{\sigma,\gamma}(\theta,R_2,\alpha,\beta)-\log R_1+\frac12(\log\theta-1)\right)\,.
\end{equation}
\item[iii)] $RBM_{\sigma\sigma}\xleftrightarrow{LT} RBM_{\rho^2}$:
\begin{equation} A_{\rho^2}(\theta,\alpha,\beta)=\sup_{R_1,R_2>0}\left(A_{\sigma\sigma}(R_1,R_2)-\frac{\alpha R_1^2+(1-\alpha)R_2^2}{2\theta}+\log(R_1^\alpha R_2^{1-\alpha})-\sqrt{\alpha(1-\alpha)}r(R_1,R_2)-\frac12(\log\theta-1)\right)\,;
\end{equation}
\begin{equation} A(R_1,R_2)=\inf_{\theta_1,\theta_2>0}\left(\frac{\alpha R_1^2}{2\theta_1}+\frac{(1-\alpha)R_2^2}{2\theta_2}+A_{\rho^2}(\theta_1,\theta_2,\alpha,\beta)-\log(R_1^\alpha R_2^{1-\alpha})+\sqrt{\alpha(1-\alpha)}r(R_1,R_2)+\frac12(\log\theta_1^\alpha\theta_2^{1-\alpha}-1)\right)\,. 
\end{equation}
\end{itemize}

Let $A_{N_1,N_2}$ denote the free energy of $HM_{\sigma}$. It holds $P$-a.s.
\begin{equation} \lim_{N_1,N_2\to\infty} A_{N_1,N_2} = \alpha\min_{2q\geq \beta(1-\alpha)\lambda_+}\left(q R^2 -\frac 12\int\rho_{MP}(\lambda;\alpha)\log(2q-\beta(1-\alpha)\lambda) d\lambda-\log R-\frac12\right)\,.
\end{equation}

Let $A_{N_1,N_2}$ denote the free energy of $RBM_{\sigma\sigma}$ and $\alpha\leq \frac 12$. It holds $P$-a.s.
\begin{eqnarray}
\lim_{N_1,N_2\to\infty} A_{N_1,N_2} &=&\min_{ab\geq \beta^2(1-\alpha)\lambda_+}\left(\frac{R^2}{2}\left(\alpha a + (1-\alpha) b\right) -\frac 1 2 (1-2\alpha)\log(b)\right. \nonumber \\
 &-&\left.\frac \alpha2\int\rho_{MP}(\lambda;\alpha)\log(ab-\beta^2(1-\alpha)\lambda) d\lambda-\log R-\frac12\right) \,.


\end{eqnarray}

For any $a>\lambda_+$ there is a $c>0$ such that
\begin{equation} E[A_{N_1,N_2}(\beta,R)1_{\{\|\frac{\Xi\Xi^T}{N_2}\|_{op}>a\}}]=\OOO{e^{-cN_1}}\,. 
\end{equation}

For any $a>\bar\sigma$ we compute
$$
E[e^{\alpha\beta\sum_{i\in[N_1]}\sigma_i\tilde x_i\tilde y_i}]=E[e^{\beta\sum_{i\in[N_1]}\sigma_i\tilde x_i\tilde y_i}1_{\{\max_{i\in[N_1]}\sigma_i\leq a\}}]+E[e^{\beta\sum_{i\in[N_1]}\sigma_i\tilde x_i\tilde y_i}1_{\{\max_{i\in[N_1]}\sigma_i>a\}}]\,.
$$
The first summand is easily estimated by
\begin{equation} E[e^{\beta\sum_{i\in[N_1]}\sigma_i\tilde x_i\tilde y_i}1_{\{\max_{i\in[N_1]}\sigma_i\leq a\}}]\leq E[e^{\beta a\sum_{i\in[N_1]}\tilde x_i\tilde y_i}]\leq E[e^{\beta a \|\tilde x\|\|\tilde y\|}]\,. 
\end{equation}
Arguing as in the proof of \cite[Proposition 1]{legendre} we can write for a $C>0$
\begin{equation} E[e^{\beta\sum_{i\in[N_1]}\sigma_i\tilde x_i\tilde y_i}1_{\{\max_{i\in[N_1]}\sigma_i>a\}}]\leq Ca\sqrt{2\pi (N_1+N_2)}e^{\frac{\beta^2}{2(N_1+N_2)}\|\tilde x\|^2\|\tilde y\|^2}\,.
\end{equation}
Then (\ref{eq:bound1}) and (\ref{eq:bound2}) give an annealed bound for the free energy:
\begin{equation}
\lim\sup_{N_1,N_2} A_N\leq \max\left(\bar\sigma\beta\sqrt{\alpha(1-\alpha)}R^2\,,\,\,\frac12 \beta^2\alpha(1-\alpha)R^2_1R^2_2 \right)<\infty\,. 
\end{equation}

With this bound at hand, we repeat mutatis mutandis the steps of the proof of \cite[Lemma 1]{legendre} to get
\begin{equation}
E[A_{N_1,N_2}1_{\{\max_{i\in[N_1]}\sigma_i>\bar\sigma\}}]\leq\sqrt{\alpha(1-\alpha)\beta^2R^4+a^2}\sqrt{P(\|\Xi\Xi^T/N_2-\mathbb I\|_{op}\geq t+\sqrt{\lambda_+}-1)}
\end{equation}
and the assert follows from (\ref{eq:impo-spectrum}).

Let $A_{N_1,N_2}$ be the free energy of $HM_{\rho}$. There is $f(\lambda_+,\beta)$ continuous and bounded for which
\begin{equation} \lim\sup_{N_1,N_2} E[A_{N_1,N_2}]\leq f(\lambda_+,\beta)\,. 
\end{equation}

Let $A_{N_1,N_2}$ be the free energy of $RBM_{\rho^2}$. There is $f(\lambda_+,\beta)$ continuous and bounded for which
\begin{equation} \lim\sup_{N_1,N_2} E[A_{N_1,N_2}]\leq f(\lambda_+,\beta)\,. 
\end{equation}

Same proof as before, noting
\begin{eqnarray}
\beta(1-\alpha)\sum_{i}\sigma_ix_iy_i-\sqrt{N_1N_2}r\left(\frac{\|x\|}{\sqrt {N_1}}, \frac{\|y\|}{\sqrt {N_2}}\right)&\leq& \beta(1-\alpha)a\|x\|\|y\|-\sqrt{N_1N_2}r\left(\frac{\|x\|}{\sqrt {N_1}}\right)\nonumber\\
&\leq&\max_{R_1,R_2}\left(\beta(1-\alpha)aR_1R_2-r(R_1,R_2)\right)\,\nonumber
\end{eqnarray}
for any $a>\sigma_+$.

Let $R,\delta>0$, $N\in\mathbb{N}$. It holds for some $C,c>0$
\begin{eqnarray}
\int_{\{\|x\|^2\geq R^2N_1^{1+\delta}\}} \rho_{N_1}(dx)e^{-\beta H_{N_1,N_2}(x)}&\leq& C e^{-cN_1^{1+\delta}}\,, \\
\int_{\{\|x\|^2\geq R^2N_1^{1+\delta}\}} \gamma_{N_1,\theta}(dx)\sigma_{R,N_2}(dy)e^{-\beta H_{N_1,N_2}(x,y)}&\leq& C e^{-cN_1^{1+\delta}}\,, \\
\int_{\{\|x\|^2\geq R^2N_1^{1+\delta}\}\cup \{\|y\|^2\geq R^2N_2^{1+\delta}\}} \rho_{N_1,N_2}^2(dxdy)e^{-\beta H_{N_1,N_2}(x,y)}&\leq& C e^{-cN_1^{1+\delta}} \,.
\end{eqnarray}

We prove only (\ref{eq:coda1}), as (\ref{eq:coda2}), (\ref{eq:coda3}) are similar. Let us write
\begin{eqnarray}
\int_{\{\|x\|^2\geq R^2N_1^{1+\delta}\}} \rho(dx)e^{-\beta H_{N_1,N_2}(x)}&\leq& e^{-\frac{R^2N_1^{1+\delta}}{2\theta}}\int_{\{\|x\|^2\geq R^2N_1^{1+\delta}\}} \gamma_{N_1,2\theta}(dx)e^{-\beta H_{N_1,N_2}(x)-N_1r\left(\frac{\|x\|}{\sqrt N_1}\right)}\nonumber\\
&\leq&e^{-\frac{R^2N_1^{1+\delta}}{2\theta}} Z_{N_1,N_2}(2\theta) =\exp\left( (N_1+N_2)A_{N_1,N_2}(2\theta)-\frac{R^2N_1^{1+\delta}}{2\theta}\right)\,. \nonumber
\end{eqnarray}
Here we have emphasised the dependence on $\theta$ of partition function and free energy. Then (\ref{eq:coda1}) follows from Lemma \ref{lemma:apriori-bound-HM}.

For any $\eta>0$ small enough we have
\begin{eqnarray}
\int_{S_{N_1,R,\varepsilon}^c}\frac{dz}{(2\pi)^{\frac {N_1}2}} e^{-\sum_i^{N_1}(q-\frac{\beta(1-\alpha)}{2}\lambda_i)z_i^2}&\leq&\exp\left[N_1\left(\eta\left(R^2-\frac\varepsilon {N_1}\right)-\frac{1}{2N_1}\sum_j\log(2q-\beta\lambda_j+2\eta)\right)\right]\nonumber\\
&+&\exp\left[N_1\left(-\eta\left(R^2+\frac\varepsilon {N_1}\right)-\frac{1}{2N_1}\sum_j\log(2q-\beta\lambda_j-2\eta)\right)\right]\nonumber.
\end{eqnarray}

\noindent Note now that the r.h.s. is $o(e^{-N})$ if $\frac\varepsilon N\to\infty$ as $N\to\infty$. So the greatest contribution is at the scale $\varepsilon=\tilde\varepsilon N$, $\tilde\varepsilon>0$ independent on $N_1$. Therefore
\begin{equation} \lim\inf_{N_1,N_2}\widehat A_{N_1,N_2,\tilde\varepsilon}\geq\max\left(\tilde A(q), A^1_{\tilde\varepsilon}(\eta; q), A^2_{\tilde\varepsilon}(\eta; q)\right),
\end{equation}
with
\begin{eqnarray}
A^1_{\tilde\varepsilon}(\eta; q)&=&\alpha(q+\eta)R^2-\alpha\tilde\varepsilon\eta-\frac\alpha2\int d\lambda\rho_{MP}(\lambda;\alpha)\log(2(q+\eta)-\beta\lambda)-\alpha\log R-\frac\alpha2;\\
A^2_{\tilde\varepsilon}(\eta; q)&=&\alpha(q-\eta)R^2-\alpha\tilde\varepsilon\eta-\frac\alpha2\int d\lambda\rho_{MP}(\lambda;\alpha)\log(2(q-\eta)-\beta\lambda)-\alpha\log R-\frac\alpha2.
\end{eqnarray}

With this choice of $q$, relation (\ref{eq:max( , , )}) gives
\begin{equation}
\lim\inf_{N_1,N_2} \widehat A_{N_1,N_2.\tilde \varepsilon}\geq \min_{q\geq\beta\lambda_+}\tilde A(q) \,.
\end{equation}
As $\tilde\varepsilon$ can be taken arbitrarily small, we recover (\ref{eq:AHMsfer}).

To do so we introduce
\begin{eqnarray}
\Delta_-(q;\eta)&:=&\tilde A(q)-A^1_{\tilde\varepsilon}(\eta; q)= -\alpha\eta(R^2-\tilde\varepsilon)+\frac\alpha2\int d\lambda\rho_{MP}(\lambda;\alpha)\log\left(\frac{2(q+\eta)-\beta\lambda}{2q-\beta\lambda}\right);\\
\Delta_+(q;\eta)&:=&\tilde A(q)-A^2_{\tilde\varepsilon}(\eta; q)= \alpha\eta(R^2+\tilde\varepsilon)+\frac\alpha2\int d\lambda\rho_{MP}(\lambda;\alpha)\log\left(\frac{2(q-\eta)-\beta\lambda}{2q-\beta\lambda}\right)\,.
\end{eqnarray}

\noindent As a function of $\eta$, $\Delta_\pm(q;\eta)$ are continuous and differentiable, vanishing in $\eta=0$ and with $\lim_{\eta\to+\infty}\Delta_\pm(q,\eta)=\pm\infty$. Moreover $\Delta_+(q;\eta)$ is uniformly convex and $\Delta_-(q;\eta)$ uniformly concave. Thus $\Delta_-(q;\eta)$ assumes a positive maximum iff the derivative in $\eta=0$ is positive, that is
\begin{equation} 0<-(R^2-\tilde\varepsilon)+\int d\lambda\frac{\rho_{MP}(\lambda;\alpha)}{2q-\beta\lambda}=\tilde \varepsilon-\partial_q \tilde A(q)\,.
\end{equation}

\noindent Likewise for $\Delta_+(q;\eta)$ is always positive iff 
$\left.\partial_\eta \Delta_+(q;\eta)\right|_{\eta=0}\geq0$, \textit{i.e. }
\begin{equation} 0\leq(R^2+\tilde\varepsilon)+\int d\lambda\frac{\rho_{MP}(\lambda;\alpha)}{2q-\beta\lambda}=\tilde \varepsilon+\partial_q \tilde A(q).
\end{equation}

The first summand is easily estimated by
\begin{equation} E[e^{\beta\sum_{i\in[N_1]}\sigma_i\tilde x_i\tilde y_i}1_{\{\max_{i\in[N_1]}\sigma_i\leq a\}}]\leq E[e^{\beta a\sum_{i\in[N_1]}\tilde x_i\tilde y_i}]\leq E[e^{\beta a \|\tilde x\|\|\tilde y\|}]\,. 
\end{equation}

Arguing as in the proof of \cite[Proposition 1]{legendre} we can write for a $C>0$
\begin{equation} E[e^{\beta\sum_{i\in[N_1]}\sigma_i\tilde x_i\tilde y_i}1_{\{\max_{i\in[N_1]}\sigma_i>a\}}]\leq Ca\sqrt{2\pi (N_1+N_2)}e^{\frac{\beta^2}{2(N_1+N_2)}\|\tilde x\|^2\|\tilde y\|^2}\,.
\end{equation}

Then (\ref{eq:bound1}) and (\ref{eq:bound2}) give an annealed bound for the free energy:
\begin{equation}
\lim\sup_{N_1,N_2} A_N\leq \max\left(\bar\sigma\beta\sqrt{\alpha(1-\alpha)}R^2\,,\,\,\frac12 \beta^2\alpha(1-\alpha)R^2_1R^2_2 \right)<\infty\,. 
\end{equation}

With this bound at hand, we repeat mutatis mutandis the steps of the proof of \cite[Lemma 1]{legendre} to get
\begin{equation}
E[A_{N_1,N_2}1_{\{\max_{i\in[N_1]}\sigma_i>\bar\sigma\}}]\leq\sqrt{\alpha(1-\alpha)\beta^2R^4+a^2}\sqrt{P(\|\Xi\Xi^T/N_2-\mathbb I\|_{op}\geq t+\sqrt{\lambda_+}-1)}
\end{equation}
and the assert follows from (\ref{eq:impo-spectrum}).

Thus by (\ref{eq:shells-surface})
\begin{eqnarray}
\varepsilon^2\hat{Z}_{N_1,N_2,\varepsilon}&\leq& \exp\left(\frac {R^2}{2} (aN_1+b N_2)\right) \frac{(2\pi)^{\frac{N_1}{2}} (2\pi)^{\frac{N_2}{2}} }{S^R_{N_1} S^R_{N_2}} \int \frac{dx dy}{\sqrt{2\pi}^N}\exp\left( -\frac 12\sum_{i=1}^{N_2} (z_i^T,M_i z_i)\right),\nonumber\\ 

&=& \exp\left(\frac {R^2}{2} (aN_1+b N_2)\right) \frac{(2\pi)^{\frac{N_1}{2}} (2\pi)^{\frac{N_2}{2}} }{S^R_{N_1} S^R_{N_2}} b^{-\frac{N_2-N_1}{2}} \prod_{i=1}^{N_1}(ab-\beta^2(1-\alpha)\sigma^2_i)^{-\frac 12}\,.
\end{eqnarray}

A direct inspection shows that $A(a,b)$ is jointly uniformly convex for any $\alpha\in[0,1/2]$ if $ab>(1-\alpha)\beta^2\lambda_+$, therefore
\begin{equation} \lim\sup_{N_1,N_2}A_{N_1,N_2}\leq \min_{ab>(1-\alpha)\beta^2\lambda_+} \bar A(a,b)\,. 
\end{equation}

We record for later use the gradient coordinates 
\begin{eqnarray}
\partial_a \bar A(a,b)&=&\frac{\alpha R^2}{2}-\frac\alpha2\int \rho_{MP}(d\lambda;\alpha)\frac{b}{ab- (1-\alpha)\beta^2\lambda}\,; \\
\partial_b \bar A(a,b)&=&\frac{(1-\alpha)R^2}{2} -\frac{1-2\alpha}{2b}-\frac\alpha2\int \rho_{MP}(d\lambda;\alpha)\frac{a}{ab- (1-\alpha)\beta^2\lambda}\,. \end{eqnarray}

We consider four contributions according to the following decomposition. Let $\kappa\in\{-1,1\}$ and put
\begin{eqnarray}
S_\varepsilon^{\kappa,1}&:=&\{x\in\mathbb{R}^{N_1}\,, y\in\mathbb{R}^{N_2}\,:\,\, \kappa(\|x\|^2-R^2N_1)\geq \varepsilon N_1\,\}\,,\nonumber\\
S_\varepsilon^{\kappa,2}&:=&\{x\in\mathbb{R}^{N_1}\,, y\in\mathbb{R}^{N_2}\,:\,\, \kappa(\|y\|^2-R^2N_2)\geq \varepsilon N_2\,\}\,.\nonumber 
\end{eqnarray}
Thus $S_\varepsilon^c=\bigcup_{\kappa\in\{-1,1\},j\in\{1,2\}}S_\varepsilon^{\kappa,j}$. Moreover we pick $\eta>0$ small enough and set
\begin{eqnarray}
M^{(\kappa,j)}_i(\eta) &:=&
  \left( {\begin{array}{cc}
   a+(2-j)\kappa\eta & -\beta\sqrt{1-\alpha}\sigma_i \\
   -\beta\sqrt{1-\alpha}\sigma_i & b+(j-1)\kappa\eta \\
\end{array} } \right)\,,\quad i\in[N_1]\nonumber\\ 
M^{(\kappa,j)}_i(\eta)&:=&\mathrm{diag}(0,b+(j-1)\kappa\eta)\,,\quad i=N_1+1,\ldots , N_2\,.\nonumber
\end{eqnarray}




























Also, we put
\begin{eqnarray}
Z_{N_1,N_2,\varepsilon}^{\kappa,j}&:=& \exp\left(\frac {R^2}{2} (aN_1+b N_2)+\frac{(2-j)N_1\kappa\eta a}{2}+\frac{(j-1)N_2\kappa\eta b}{2}-\eta \varepsilon N_j\right)\nonumber\\
&&\int_{S_\varepsilon^{\kappa,j}} \frac{dxdy}{|S_1||S_2|}\exp\left( -\frac 1 2 \sum_{i=1}^{N_2} (z_i^T,M^{(\kappa,j)}_i(\eta) z_i)\right)\nonumber\\
\end{eqnarray}
so that 
$$
(\ref{eq:II-termRBM})=-\sum_{\kappa\in\{-1,1\},j=1,2} Z_{N_1,N_2,\varepsilon}^{\kappa,j}\,. 
$$

We conclude that for any $\eta>0$ sufficiently small and $a,b$ with $ab>(1-\alpha)\beta^2\lambda_+$ 
\begin{equation}
\lim\sup_{N_1,N_2} \widehat A_{N_1,N_2,\varepsilon}\geq \max(\bar A(a,b), \{A_\varepsilon^{\kappa, j}(\eta; a,b)\}_{\kappa\in\{-1,1\},j\in\{1,2\}})\,,
\end{equation}
where 
\begin{eqnarray}
A_\varepsilon^{\kappa,j}(\eta; a,b)&:=&-\eta\varepsilon+\frac12\alpha a(R^2+(2-j)\kappa\eta)+\frac12(1-\alpha) b(R^2+(j-1)\kappa\eta)\nonumber\\
&-&\log R -\frac12-\frac{1-2\alpha}{2}\log (b+(j-1)\kappa\eta)\nonumber\\
&-&\frac\alpha2 \int \rho_{MP}(d\lambda;\alpha)\log((a+(2-j)\kappa\eta)(b+(j-1)\kappa\eta)- (1-\alpha)\beta^2\lambda)\,. \nonumber
\end{eqnarray}

In analogy with the proof of Theorem \ref{Th:HM-sfer} we define 
\begin{eqnarray}
\Delta_{\varepsilon}^{\kappa,j}(\eta)&:=&\bar A(a,b)-A_\varepsilon^{\kappa,j}(\eta; a,b)\nonumber\\
&=&\eta \varepsilon-(2-j)\kappa\frac{\eta\alpha a}{2}-(j-1)\kappa\frac{\eta(1-\alpha) b}{2}+\frac{1-2\alpha}{2}\log(b+(j-1)\kappa\eta)\nonumber\\
&+&\frac\alpha2 \int \rho_{MP}(d\lambda;\alpha)\log\left(\frac{(a+(2-j)\kappa\eta)(b+(j-1)\kappa\eta)- (1-\alpha)\beta^2\lambda}{ab-(1-\alpha)\beta^2\lambda}\right)\,.\nonumber
\end{eqnarray}
We need to show that $\Delta_{\varepsilon}^{\kappa,j}(\eta)\geq0$ for $\eta>0$ small. As before, to do so it suffices to prove the derivative in the origin to be non-negative uniformly in $\varepsilon>0$. Bearing in mind (\ref{eq:grad1RBM}), (\ref{eq:grad2RBM}) we have
\begin{eqnarray}
\frac{d}{d\eta} \Delta_{\varepsilon}^{\kappa,j}(\eta)\big|_{\eta=0}&=&\varepsilon+(2-j)\kappa\left(-\frac{a\alpha R^2}{2}+\frac\alpha2 \int \rho_{MP}(d\lambda;\alpha)\left(\frac{b}{ab-(1-\alpha)\beta^2\lambda}\right)\right)\nonumber\\
&+&(j-1)\kappa\left(-\frac{b(1-\alpha) R^2}{2}+\frac{1-2\alpha}{2b}+\frac\alpha2 \int \rho_{MP}(d\lambda;\alpha)\left(\frac{a}{ab-(1-\alpha)\beta^2\lambda}\right)\right)\nonumber\\
&=&\varepsilon-(2-j)\kappa\partial_a\bar A-(j-1)\kappa\partial_b\bar A\geq0\,. \nonumber
\end{eqnarray}

On the other hand by assumption
\begin{equation}
P((k+1)a\geq \lambda^*> ka)\leq 2e^{-ca^2k^2N_1}\,,\quad c>0\,. 
\end{equation}

In conclusion
\begin{equation}
E[A_{N_1,N_2}]\leq \sum_{k\geq0}e^{-ca^2k^2N_1}\max_{R\geq0}\left(R^2(\beta a(k+1))-r\left(R\right)\right)=:f(a,\beta)\,,
\end{equation}
a continuous bounded function. In particular the estimate holds also for $a\to\lambda_+$.

Let us write
\begin{eqnarray}
\int_{\{\|x\|^2\geq R^2N_1^{1+\delta}\}} \rho(dx)e^{-\beta H_{N_1,N_2}(x)}&\leq& e^{-\frac{R^2N_1^{1+\delta}}{2\theta}}\int_{\{\|x\|^2\geq R^2N_1^{1+\delta}\}} \gamma_{N_1,2\theta}(dx)e^{-\beta H_{N_1,N_2}(x)-N_1r\left(\frac{\|x\|}{\sqrt N_1}\right)}\nonumber\\
&\leq&e^{-\frac{R^2N_1^{1+\delta}}{2\theta}} Z_{N_1,N_2}(2\theta) =\exp\left( (N_1+N_2)A_{N_1,N_2}(2\theta)-\frac{R^2N_1^{1+\delta}}{2\theta}\right)\,. \nonumber
\end{eqnarray}
Here we have emphasised the dependence on $\theta$ of partition function and free energy.

We notice now that by continuity for any $x\in S^{[i]}_{\varepsilon,N_1}$
\begin{equation} \frac{\|x\|^2}{2\theta}+N_1r\left(\frac{\|x\|}{\sqrt N_1}\right)=\frac{\tilde R_i^2N_1}{2\theta}+N_1r\left(\tilde R_i\right)+\OOO{\varepsilon} 
\end{equation}
where $\tilde R_i\in[R_i, R_{i+1}]$. Therefore
\begin{equation}
Z^{\rho}_{N_1,N_2,\beta}[i]=e^{-\frac{\tilde R_i^2N_1}{2\theta}-N_1r\left(\tilde R_i \right)-\OOO{\varepsilon}}\frac{|S^{[i]}_{N_1,\varepsilon}|}{\sqrt{2\pi\theta}^{N_1}}\int \sigma^{[i]}_{N_1,\varepsilon}(dx)e^{-\beta H_{N_1,N_2}(x)}\,
